#!/usr/bin/env bash
# Pushes 2025-12-31 to 2026-01-06 for all 10 hospitals (every disease), with an influenza (D004) surge hidden at
# H001, H002 and H003, then runs the outbreak scan. Run from the project root with the backend up on port 8000:
#     bash models/objectiveB/demo_outbreak_curl.sh
# Each row below is one hospital, one day, one disease: n = cases that day, symptoms = how many of them had each symptom.
# The API key is read from .env, so it is not stored in this file.
set -euo pipefail
KEY=$(grep '^OBJECTIVE_E_API_KEY=' .env | cut -d= -f2- | tr -d "'\"")
URL=${URL:-http://localhost:8000}/api/outbreak
push() { curl -s -X POST "$URL/summaries" -H "X-API-Key: $KEY" -H "Content-Type: application/json" -d @-; echo; }

